// gradebook.h
#pragma once
#include <string>
#include <vector>

class Gradebook {
public:
    void add(int score);                    // declared here...
    double average() const;
    int count() const { return static_cast<int>(scores_.size()); }  // defined in class: implicitly inline.
private:
    std::vector<int> scores_;
};

std::string letter(double avg);             // free function: declaration.

// gradebook.cpp
#include "gradebook.h"
void Gradebook::add(int score) { scores_.push_back(score); }   // ...defined once here.
double Gradebook::average() const {
    if (scores_.empty()) return 0.0;
    double sum = 0;
    for (int s : scores_) sum += s;
    return sum / scores_.size();
}
std::string letter(double avg) { return avg >= 90 ? "A" : avg >= 80 ? "B" : "C"; }
```

